const tagType=v=>v.kind==='literal'?(['true','false'].includes(v.raw)?'b':v.raw.match(/[bBsSlLfFdD]$/)?.[0].toLowerCase()||(/[.eE]/.test(v.raw)?'d':'i')):v.kind;
const protectedKeys=new Set(['transformation','block_state','item','item_display','Pos','Rotation','UUID','id','interpolation_duration','start_interpolation','teleport_duration']);
export function parseEntityNbt(source=''){
 if(typeof source!=='string'||source.length>8192)throw new Error('NBT는 8,192자까지 입력할 수 있습니다.');if(!source.trim())return {kind:'compound',entries:[]};let i=0,nodes=0;const fail=message=>{throw new Error('NBT '+(i+1)+'번째 문자: '+message);},space=()=>{while(/\s/.test(source[i]||'')&&i<source.length)i++;};
 function quoted(){const quote=source[i++];let raw=quote,value='';while(i<source.length){let c=source[i++];raw+=c;if(c.charCodeAt(0)<32)fail('문자열 안에는 실제 줄바꿈을 넣을 수 없습니다.');if(c===quote)return {kind:'string',raw,value};if(c==='\\'){if(i>=source.length)fail('문자열 끝');c=source[i++];if(c!=='\\'&&c!==quote)fail('따옴표와 역슬래시만 이스케이프할 수 있습니다.');raw+=c;value+=c;}else value+=c;}fail('문자열 닫는 따옴표가 없습니다.');}
 function value(depth=0){space();if(depth>16||++nodes>1024)fail('너무 복잡한 NBT입니다.');const c=source[i];if(c==='"'||c==="'")return quoted();if(c==='{'){i++;let entries=[],keys=new Set();space();while(source[i]!=='}'){let key;if(source[i]==='"'||source[i]==="'")key=quoted().value;else{const start=i;while(/[A-Za-z0-9._+-]/.test(source[i]||'')&&i<source.length)i++;key=source.slice(start,i);}if(!key)fail('키 이름이 필요합니다.');space();if(source[i++]!==':')fail('키 다음에 :가 필요합니다.');if(keys.has(key))fail('중복 키 '+key);keys.add(key);entries.push([key,value(depth+1)]);space();if(source[i]===','){i++;space();if(source[i]==='}')fail('마지막 쉼표를 제거하세요.');}else if(source[i]!=='}')fail(', 또는 }가 필요합니다.');}i++;return {kind:'compound',entries};}if(c==='['){i++;space();let typed=null;if(/[BIL]/.test(source[i]||'')&&source[i+1]===';'){typed=source[i];i+=2;}let values=[];space();while(source[i]!==']'){values.push(value(depth+1));space();if(source[i]===','){i++;space();if(source[i]===']')fail('마지막 쉼표를 제거하세요.');}else if(source[i]!==']')fail(', 또는 ]가 필요합니다.');}i++;if(typed&&values.some(v=>v.kind!=='literal'||tagType(v)!==typed.toLowerCase()))fail('타입 배열의 숫자 형식이 다릅니다. B는 1b, I는 1, L은 1L을 사용하세요.');if(!typed&&values.some(v=>tagType(v)!==tagType(values[0])))fail('목록의 값은 같은 NBT 타입이어야 합니다.');return {kind:'list',typed,values};}const start=i;while(/[A-Za-z0-9._+:-]/.test(source[i]||'')&&i<source.length)i++;const raw=source.slice(start,i);if(!raw)fail('값이 필요합니다.');if(!/^[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?[bBsSlLfFdD]?$/.test(raw)&&!['true','false'].includes(raw))return {kind:'string',raw,value:raw};return {kind:'literal',raw};}
 const root=value();space();if(i!==source.length)fail('닫는 괄호 뒤에 문자가 있습니다.');if(root.kind!=='compound')fail('NBT는 { } 형식으로 입력하세요.');for(const [key,v]of root.entries){if(protectedKeys.has(key))throw new Error(key+'는 물체 편집 메뉴에서 설정하세요.');if(key==='Tags'&&(v.kind!=='list'||v.typed||v.values.some(v=>v.kind!=='string')))throw new Error('Tags는 문자열 목록으로 입력하세요.');}return root;
}
const serialize=n=>n.kind==='compound'?'{'+n.entries.map(([k,v])=>JSON.stringify(k)+':'+serialize(v)).join(',')+'}':n.kind==='list'?'['+(n.typed?n.typed+';':'')+n.values.map(serialize).join(',')+']':n.raw;
export function entityMetadata(object){const root=parseEntityNbt(object.entityNbt||''),tags=Array.isArray(object.tags)||object.tags==null?[...(object.tags||[])]:null,extra=[];if(!tags)throw new Error('태그는 문자열 목록이어야 합니다.');for(const [key,v]of root.entries)if(key==='Tags')tags.push(...v.values.map(v=>v.value));else extra.push(JSON.stringify(key)+':'+serialize(v));if(tags.length>64||tags.some(t=>typeof t!=='string'||!t.length||t.length>80||/[\x00-\x1f]/.test(t)))throw new Error('태그는 80자 이하의 이름으로 최대 64개까지 설정하세요.');return {tags:[...new Set(tags)],extra:extra.length?','+extra.join(','):''};}
